inner_script:
$ProgressPreference = 'SilentlyContinue'
$ErrorActionPreference = 'Stop'
$r = [ordered]@{scope='READ_ONLY_ELEVATED_VM_INVENTORY'; utc=[DateTime]::UtcNow.ToString('o')}
$r.administrator = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
try {
  $r.features = @(Get-WindowsOptionalFeature -Online | Where-Object { $_.FeatureName -match 'Hyper-V|HypervisorPlatform|VirtualMachinePlatform|Subsystem-Linux' } | Select-Object FeatureName,State)
  $r.hcsdiag_output = @(& C:\Windows\System32\hcsdiag.exe list 2>&1 | Out-String)
  $r.hcsdiag_exit = $LASTEXITCODE
  $r.hyperv_directories = @('C:\ProgramData\Microsoft\Windows\Hyper-V','C:\Users\Public\Documents\Hyper-V') | ForEach-Object {
    $v = [ordered]@{path=$_;exists=(Test-Path -LiteralPath $_)}
    if ($v.exists) { $v.entries = @(Get-ChildItem -LiteralPath $_ -Force -Recurse | Select-Object FullName,Mode,Length) }
    $v
  }
  try { $r.registered_vms = @(Get-CimInstance -Namespace root/virtualization/v2 -ClassName Msvm_ComputerSystem | Select-Object Name,ElementName,Caption,EnabledState) } catch { $r.registered_vms_error=$_.Exception.Message }
  $r.status = 'READ_ONLY_INVENTORY_COMPLETE'
} catch { $r.status='READ_ONLY_INVENTORY_FAILED'; $r.error=$_.Exception.Message }
$r.finished_utc = [DateTime]::UtcNow.ToString('o')
$r | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath '\\wsl.localhost\Ubuntu\tmp\src001-vm-7a772f0\elevated-inventory.json' -Encoding UTF8
